insert into public.questions (id, kind, prompt, options, marks) values ('3631afe8-3f2e-5c63-8c96-b9bb4a629457', 'short', 'Distinguish between the roles of the nervous system and the endocrine system in sending messages.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3631afe8-3f2e-5c63-8c96-b9bb4a629457', 'The nervous system sends electrical impulses along neurons [1]; the endocrine system sends hormones in the blood [1]; nervous messages are faster and short-lived, hormonal messages slower and longer-lasting [1].', 'The nervous system sends electrical impulses along neurons [1]; the endocrine system sends hormones in the blood [1]; nervous messages are faster and short-lived, hormonal messages slower and longer-lasting [1].', '[{"text": "Marking point 1", "any": ["impulse", "electrical", "neuron"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hormone", "blood"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["faster", "slower", "longer"], "all": [], "marks": 1}]'::jsonb, 'The nervous system sends electrical impulses along neurons [1]; the endocrine system sends hormones in the blood [1]; nervous messages are faster and short-lived, hormonal messages slower and longer-lasting [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
