insert into public.questions (id, kind, prompt, options, marks) values ('24d1ed5e-c4a5-53a3-83e4-e5e2460269f1', 'short', 'Using examples, explain the role of the blood in integrating organs.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('24d1ed5e-c4a5-53a3-83e4-e5e2460269f1', 'The blood transports materials and energy between organs [1]; e.g. glucose from the liver, O₂ from the lungs, urea and hormones [1]; e.g. urea from the liver to the kidneys, O₂ from lungs to muscles, so organs can depend on each other [1].', 'The blood transports materials and energy between organs [1]; e.g. glucose from the liver, O₂ from the lungs, urea and hormones [1]; e.g. urea from the liver to the kidneys, O₂ from lungs to muscles, so organs can depend on each other [1].', '[{"text": "Marking point 1", "any": ["transport", "carries"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["glucose", "oxygen", "urea", "hormone", "heat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["liver", "lungs", "kidney", "muscle"], "all": [], "marks": 1}]'::jsonb, 'The blood transports materials and energy between organs [1]; e.g. glucose from the liver, O₂ from the lungs, urea and hormones [1]; e.g. urea from the liver to the kidneys, O₂ from lungs to muscles, so organs can depend on each other [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
