insert into public.questions (id, kind, prompt, options, marks) values ('9ea3b2f3-15e7-506e-9ba8-15de6d4743cf', 'short', 'Explain how adrenaline prepares the body for vigorous activity.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9ea3b2f3-15e7-506e-9ba8-15de6d4743cf', 'Adrenaline increases heart rate and stroke volume [1]; it causes glycogen in the liver to be broken down, raising blood glucose [1]; it widens the airways and increases ventilation / diverts blood to muscles, supplying more O₂ for contraction [1].', 'Adrenaline increases heart rate and stroke volume [1]; it causes glycogen in the liver to be broken down, raising blood glucose [1]; it widens the airways and increases ventilation / diverts blood to muscles, supplying more O₂ for contraction [1].', '[{"text": "Marking point 1", "any": ["heart rate", "heart"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["glucose", "glycogen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["airway", "ventilation", "breathing", "blood to muscles", "dilate", "oxygen"], "all": [], "marks": 1}]'::jsonb, 'Adrenaline increases heart rate and stroke volume [1]; it causes glycogen in the liver to be broken down, raising blood glucose [1]; it widens the airways and increases ventilation / diverts blood to muscles, supplying more O₂ for contraction [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('7b9087dc-3846-543d-a0db-da3785567ca6', '9ea3b2f3-15e7-506e-9ba8-15de6d4743cf', 15);
