insert into public.questions (id, kind, prompt, options, marks) values ('d74d78fd-49aa-588e-90fc-76317221e351', 'short', 'Outline how you would investigate the effect of light from one side on the growth of seedlings.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
