insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3bf7d2fb-b581-57f5-985a-84bb9defb363', 'Muscles respire faster, producing more CO₂ [1]; CO₂ dissolves forming carbonic acid, lowering blood pH [1]; chemoreceptors in the brainstem detect the fall in pH [1]; the medulla sends impulses to the diaphragm and intercostal muscles to increase breathing rate and depth [1].', 'Muscles respire faster, producing more CO₂ [1]; CO₂ dissolves forming carbonic acid, lowering blood pH [1]; chemoreceptors in the brainstem detect the fall in pH [1]; the medulla sends impulses to the diaphragm and intercostal muscles to increase breathing rate and depth [1].', '[{"text": "Marking point 1", "any": ["carbon dioxide", "co2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ph decreases", "acid", "lower ph"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["chemoreceptor"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["diaphragm", "intercostal", "medulla", "brainstem"], "all": [], "marks": 1}]'::jsonb, 'Muscles respire faster, producing more CO₂ [1]; CO₂ dissolves forming carbonic acid, lowering blood pH [1]; chemoreceptors in the brainstem detect the fall in pH [1]; the medulla sends impulses to the diaphragm and intercostal muscles to increase breathing rate and depth [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
