insert into public.questions (id, kind, prompt, options, marks) values ('bacdc82d-fe16-5f6a-bede-99de08e7dfaf', 'short', 'Explain why a person is unlikely to suffer from measles twice.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bacdc82d-fe16-5f6a-bede-99de08e7dfaf', 'Memory cells specific to measles antigens remain after the first infection [1]; on re-infection they rapidly produce large amounts of antibody, eliminating the virus before symptoms develop [1].', 'Memory cells specific to measles antigens remain after the first infection [1]; on re-infection they rapidly produce large amounts of antibody, eliminating the virus before symptoms develop [1].', '[{"text": "Marking point 1", "any": ["memory cells"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["rapid", "faster", "quickly", "before symptoms"], "all": [], "marks": 1}]'::jsonb, 'Memory cells specific to measles antigens remain after the first infection [1]; on re-infection they rapidly produce large amounts of antibody, eliminating the virus before symptoms develop [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
