insert into public.questions (id, kind, prompt, options, marks) values ('27c31fdc-b965-5409-b9ab-27a304ad48e8', 'short', 'Distinguish between the innate and adaptive immune systems.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('27c31fdc-b965-5409-b9ab-27a304ad48e8', 'The innate system responds to broad categories of pathogen [1]; the adaptive system responds specifically to particular pathogens [1]; the innate system does not change during life, while the adaptive system builds up memory, so responses become more effective [1].', 'The innate system responds to broad categories of pathogen [1]; the adaptive system responds specifically to particular pathogens [1]; the innate system does not change during life, while the adaptive system builds up memory, so responses become more effective [1].', '[{"text": "Marking point 1", "any": ["broad", "non-specific", "general"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["specific"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["memory", "does not change", "more effective"], "all": [], "marks": 1}]'::jsonb, 'The innate system responds to broad categories of pathogen [1]; the adaptive system responds specifically to particular pathogens [1]; the innate system does not change during life, while the adaptive system builds up memory, so responses become more effective [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('159d6d94-7688-56fa-92c4-6486b62000fa', '27c31fdc-b965-5409-b9ab-27a304ad48e8', 20);
insert into public.questions (id, kind, prompt, options, marks) values ('2c16fdc3-cb10-5f52-b7e2-9bfb213bae1e', 'short', 'Explain how infection with HIV leads to AIDS.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2c16fdc3-cb10-5f52-b7e2-9bfb213bae1e', 'HIV infects and destroys helper T-lymphocytes [1]; so fewer B-cells are activated and antibody production falls [1]; the person cannot fight opportunistic infections, which is AIDS [1].', 'HIV infects and destroys helper T-lymphocytes [1]; so fewer B-cells are activated and antibody production falls [1]; the person cannot fight opportunistic infections, which is AIDS [1].', '[{"text": "Marking point 1", "any": ["lymphocyte", "helper t"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["antibod", "immune response"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["opportunistic", "other infections"], "all": [], "marks": 1}]'::jsonb, 'HIV infects and destroys helper T-lymphocytes [1]; so fewer B-cells are activated and antibody production falls [1]; the person cannot fight opportunistic infections, which is AIDS [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('159d6d94-7688-56fa-92c4-6486b62000fa', '2c16fdc3-cb10-5f52-b7e2-9bfb213bae1e', 21);
insert into public.questions (id, kind, prompt, options, marks) values ('a58adbf4-e108-52b5-ac7f-d5bc1f84e75f', 'short', 'Explain why antibiotics fail to control viral infections.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a58adbf4-e108-52b5-ac7f-d5bc1f84e75f', 'Viruses have no metabolism or cell structures of their own (no cell wall, no ribosomes), using the host cell''s processes [1]; so there are no bacterial processes for antibiotics to block [1].', 'Viruses have no metabolism or cell structures of their own (no cell wall, no ribosomes), using the host cell''s processes [1]; so there are no bacterial processes for antibiotics to block [1].', '[{"text": "Marking point 1", "any": ["no metabolism", "host cell", "inside cells", "own metabolism", "no cell wall", "no ribosomes"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nothing to block", "processes", "not affected", "cannot target"], "all": [], "marks": 1}]'::jsonb, 'Viruses have no metabolism or cell structures of their own (no cell wall, no ribosomes), using the host cell''s processes [1]; so there are no bacterial processes for antibiotics to block [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
