insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('40958f35-95fe-5b69-9030-f0f7383e9074', 'Phagocytes move by amoeboid movement out of capillaries to the site of infection [1]; they recognise and engulf pathogens by endocytosis [1]; lysosomes fuse with the vesicle and their enzymes digest the pathogen [1].', 'Phagocytes move by amoeboid movement out of capillaries to the site of infection [1]; they recognise and engulf pathogens by endocytosis [1]; lysosomes fuse with the vesicle and their enzymes digest the pathogen [1].', '[{"text": "Marking point 1", "any": ["amoeboid", "move", "leave the blood", "squeeze"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["engulf", "endocytosis"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lysosome", "digest", "enzymes"], "all": [], "marks": 1}]'::jsonb, 'Phagocytes move by amoeboid movement out of capillaries to the site of infection [1]; they recognise and engulf pathogens by endocytosis [1]; lysosomes fuse with the vesicle and their enzymes digest the pathogen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
